{
  "name": "SmartDisclosure",
  "description": "A frictionless, AI-powered Invention Disclosure Form (IDF) that uses conversational intelligence to extract technical details and prepare legal documentation without login barriers.",
  "requestFramePermissions": [
    "microphone"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface IDFData {
  inventorName: string;
  inventorEmail: string;
  title: string;
  problem: string;
  solution: string;
  technicalDetails: string;
  inventorsList: string;
  testingDates: string;
  publicDisclosures: string;
  upcomingDisclosures: string;
  status: 'draft' | 'submitted';
  diagramDescription?: string;
}

export interface Message {
  id: string;
  role: 'user' | 'assistant' | 'system';
  content: string;
  type?: 'text' | 'audio' | 'image';
  timestamp: number;
}

export interface SessionState {
  sessionId: string;
  messages: Message[];
  data: IDFData;
  lastUpdated: number;
}

export enum AppMode {
  LANDING = 'LANDING',
  INVENTOR = 'INVENTOR',
  ATTORNEY = 'ATTORNEY',
}

export interface AIResponseSchema {
  updatedFields: Partial<IDFData>;
  aiResponse: string;
  nextPhase?: boolean;
}

import { SessionState, IDFData, Message } from '../types';
import { INITIAL_IDF_DATA } from '../constants';

const STORAGE_KEY_PREFIX = 'smart_idf_session_';

export const getSession = (sessionId: string): SessionState | null => {
  const stored = localStorage.getItem(`${STORAGE_KEY_PREFIX}${sessionId}`);
  if (!stored) return null;
  return JSON.parse(stored);
};

export const createSession = (sessionId: string): SessionState => {
  const newSession: SessionState = {
    sessionId,
    messages: [{
      id: 'init',
      role: 'assistant',
      content: "Welcome to SmartDisclosure. To begin, please enter your full name and work email address so we can associate this disclosure with you.",
      timestamp: Date.now(),
      type: 'text'
    }],
    data: { ...INITIAL_IDF_DATA },
    lastUpdated: Date.now()
  };
  saveSession(newSession);
  return newSession;
};

export const saveSession = (session: SessionState): void => {
  localStorage.setItem(`${STORAGE_KEY_PREFIX}${session.sessionId}`, JSON.stringify(session));
};

export const submitSession = (sessionId: string): void => {
    const session = getSession(sessionId);
    if(session) {
        session.data.status = 'submitted';
        saveSession(session);
    }
}

import { GoogleGenAI, Type } from "@google/genai";
import { IDFData, Message, AIResponseSchema } from '../types';
import { SYSTEM_INSTRUCTION } from '../constants';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// We use 'gemini-2.5-flash-latest' for a balance of speed, multimodal, and reasoning.
// In the SDK, aliases map to specific models. 
// Based on instructions: 'gemini flash' -> 'gemini-flash-latest'.
// However, to ensure best performance with JSON schema and reasoning, we will use a specific preview model if available, 
// or standard flash. Let's use 'gemini-2.5-flash-001' concept via the alias.
const MODEL_NAME = 'gemini-2.5-flash-latest';

export const generateAIResponse = async (
  currentData: IDFData,
  history: Message[],
  newItem: { text?: string; audioBase64?: string; imageBase64?: string; mimeType?: string }
): Promise<AIResponseSchema> => {

  try {
    const parts: any[] = [];

    // Contextualize the model with the current state of the form
    const stateContext = `
      CURRENT IDF STATE (JSON):
      ${JSON.stringify(currentData, null, 2)}

      INSTRUCTION:
      Analyze the USER INPUT below. 
      1. Extract relevant technical or legal info to update the IDF STATE.
      2. Formulate the next follow-up question based on the empty fields in the priority order defined in the system instructions.
      3. If the user asks to "Submit", ensure all critical fields are filled, then set status to 'submitted' only if ready.
    `;

    parts.push({ text: stateContext });

    // Add History (last 5 messages for context, preventing token overflow)
    const recentHistory = history.slice(-5);
    recentHistory.forEach(msg => {
       if (msg.role !== 'system') {
           parts.push({ text: `${msg.role.toUpperCase()}: ${msg.content}` });
       }
    });

    // Add new user input
    parts.push({ text: "USER INPUT (New):" });

    if (newItem.text) {
      parts.push({ text: newItem.text });
    }

    if (newItem.imageBase64 && newItem.mimeType) {
      parts.push({
        inlineData: {
          mimeType: newItem.mimeType,
          data: newItem.imageBase64
        }
      });
    }

    if (newItem.audioBase64 && newItem.mimeType) {
       parts.push({
        inlineData: {
          mimeType: newItem.mimeType,
          data: newItem.audioBase64
        }
      });
    }

    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            updatedFields: {
              type: Type.OBJECT,
              properties: {
                inventorName: { type: Type.STRING },
                inventorEmail: { type: Type.STRING },
                title: { type: Type.STRING },
                problem: { type: Type.STRING },
                solution: { type: Type.STRING },
                technicalDetails: { type: Type.STRING },
                inventorsList: { type: Type.STRING },
                testingDates: { type: Type.STRING },
                publicDisclosures: { type: Type.STRING },
                upcomingDisclosures: { type: Type.STRING },
                diagramDescription: { type: Type.STRING },
              }
            },
            aiResponse: { type: Type.STRING },
          },
          required: ["aiResponse"]
        }
      },
      contents: {
        parts: parts
      }
    });

    if (response.text) {
      return JSON.parse(response.text) as AIResponseSchema;
    }

    throw new Error("No response from AI");

  } catch (error) {
    console.error("Gemini API Error:", error);
    return {
      updatedFields: {},
      aiResponse: "I'm having trouble processing that right now. Could you please repeat or try typing?"
    };
  }
};

import React, { useState, useRef, useEffect } from 'react';

interface AudioRecorderProps {
  onRecordingComplete: (blob: Blob) => void;
  disabled?: boolean;
}

const AudioRecorder: React.FC<AudioRecorderProps> = ({ onRecordingComplete, disabled }) => {
  const [isRecording, setIsRecording] = useState(false);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<BlobPart[]>([]);

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      mediaRecorderRef.current = new MediaRecorder(stream);
      chunksRef.current = [];

      mediaRecorderRef.current.ondataavailable = (e) => {
        if (e.data.size > 0) {
          chunksRef.current.push(e.data);
        }
      };

      mediaRecorderRef.current.onstop = () => {
        const blob = new Blob(chunksRef.current, { type: 'audio/mp3' }); // Browsers usually output webm/ogg, but we label logically for processing
        onRecordingComplete(blob);
        // Stop all tracks
        stream.getTracks().forEach(track => track.stop());
      };

      mediaRecorderRef.current.start();
      setIsRecording(true);
    } catch (err) {
      console.error("Error accessing microphone:", err);
      alert("Could not access microphone. Please check permissions.");
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
    }
  };

  return (
    <button
      onClick={isRecording ? stopRecording : startRecording}
      disabled={disabled}
      className={`p-3 rounded-full transition-all duration-300 flex items-center justify-center ${
        isRecording 
          ? 'bg-red-500 hover:bg-red-600 animate-pulse ring-4 ring-red-200' 
          : 'bg-indigo-600 hover:bg-indigo-700'
      } disabled:opacity-50 disabled:cursor-not-allowed text-white`}
      title={isRecording ? "Stop Recording" : "Start Recording"}
    >
      {isRecording ? (
        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-6 h-6">
          <path strokeLinecap="round" strokeLinejoin="round" d="M5.25 7.5A2.25 2.25 0 0 1 7.5 5.25h9a2.25 2.25 0 0 1 2.25 2.25v9a2.25 2.25 0 0 1-2.25 2.25h-9a2.25 2.25 0 0 1-2.25-2.25v-9Z" />
        </svg>
      ) : (
        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-6 h-6">
          <path strokeLinecap="round" strokeLinejoin="round" d="M12 18.75a6 6 0 0 0 6-6v-1.5m-6 7.5a6 6 0 0 1-6-6v-1.5m6 7.5v3.75m-3.75 0h7.5M12 15.75a3 3 0 0 1-3-3V4.5a3 3 0 1 1 6 0v8.25a3 3 0 0 1-3 3Z" />
        </svg>
      )}
    </button>
  );
};

export default AudioRecorder;

