import React, { useState, useRef, useEffect } from 'react';
import { Message, IDFData } from '../types';
import AudioRecorder from './AudioRecorder';
import { generateAIResponse } from '../services/geminiService';

interface ChatInterfaceProps {
  messages: Message[];
  setMessages: React.Dispatch<React.SetStateAction<Message[]>>;
  idfData: IDFData;
  setIDFData: React.Dispatch<React.SetStateAction<IDFData>>;
  onSave: () => void;
  onSubmit: () => void;
}

const ChatInterface: React.FC<ChatInterfaceProps> = ({ 
  messages, 
  setMessages, 
  idfData, 
  setIDFData,
  onSave,
  onSubmit
}) => {
  const [inputText, setInputText] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  // Helper to process AI response
  const processInput = async (
      text: string | undefined, 
      audioBlob: Blob | undefined, 
      imageFile: File | undefined
  ) => {
    setIsProcessing(true);
    const timestamp = Date.now();

    // 1. Add User Message to UI
    let userContent = text || '';
    let msgType: 'text' | 'audio' | 'image' = 'text';

    if (audioBlob) {
        userContent = '🎤 [Audio Recorded]';
        msgType = 'audio';
    } else if (imageFile) {
        userContent = `🖼️ [Image Uploaded: ${imageFile.name}]`;
        msgType = 'image';
    }

    const newMessage: Message = {
      id: `msg-${timestamp}`,
      role: 'user',
      content: userContent,
      type: msgType,
      timestamp
    };

    const newHistory = [...messages, newMessage];
    setMessages(newHistory);
    setInputText('');

    // 2. Prepare Payload for Gemini
    let audioBase64: string | undefined;
    let imageBase64: string | undefined;
    let mimeType: string | undefined;

    if (audioBlob) {
        const reader = new FileReader();
        reader.readAsDataURL(audioBlob);
        await new Promise(resolve => reader.onloadend = resolve);
        // data:audio/mp3;base64,.....
        const base64Result = reader.result as string;
        audioBase64 = base64Result.split(',')[1];
        mimeType = 'audio/mp3'; 
    }

    if (imageFile) {
        const reader = new FileReader();
        reader.readAsDataURL(imageFile);
        await new Promise(resolve => reader.onloadend = resolve);
        const base64Result = reader.result as string;
        imageBase64 = base64Result.split(',')[1];
        mimeType = imageFile.type;
    }

    // 3. Call AI
    const aiResult = await generateAIResponse(idfData, newHistory, {
        text: text,
        audioBase64,
        imageBase64,
        mimeType
    });

    // 4. Update State
    if (aiResult.updatedFields) {
        const updatedData = { ...idfData, ...aiResult.updatedFields };
        setIDFData(updatedData);
    }

    // 5. Add AI Response to UI
    const aiMessage: Message = {
        id: `msg-${Date.now()}`,
        role: 'assistant',
        content: aiResult.aiResponse,
        timestamp: Date.now()
    };
    setMessages(prev => [...prev, aiMessage]);

    // Trigger auto-save in parent
    setTimeout(onSave, 100); 

    setIsProcessing(false);
  };

  const handleSendText = () => {
    if (!inputText.trim()) return;
    processInput(inputText, undefined, undefined);
  };

  const handleAudioComplete = (blob: Blob) => {
      processInput(undefined, blob, undefined);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files[0]) {
          processInput(undefined, undefined, e.target.files[0]);
      }
      // Reset input
      if(fileInputRef.current) fileInputRef.current.value = '';
  };

  return (
    <div className="flex flex-col h-full bg-slate-50 relative">
      {/* Session Guard Header */}
      <div className="bg-indigo-50 text-indigo-800 text-xs px-4 py-2 text-center border-b border-indigo-100 flex justify-between items-center">
        <span>Session Secure • Auto-saving</span>
        <button 
            onClick={onSubmit}
            className="bg-green-600 text-white px-3 py-1 rounded hover:bg-green-700 text-xs font-bold transition-colors shadow-sm"
        >
            SUBMIT DISCLOSURE
        </button>
      </div>

      {/* Messages Area */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {messages.map((msg) => (
          <div
            key={msg.id}
            className={`flex w-full ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
          >
            <div
              className={`max-w-[85%] p-4 rounded-2xl shadow-sm text-sm leading-relaxed ${
                msg.role === 'user'
                  ? 'bg-indigo-600 text-white rounded-tr-none'
                  : 'bg-white border border-slate-200 text-slate-800 rounded-tl-none'
              }`}
            >
              {msg.type === 'image' && <div className="text-xs opacity-75 mb-1 font-bold tracking-wider">ATTACHMENT</div>}
              {msg.type === 'audio' && <div className="text-xs opacity-75 mb-1 font-bold tracking-wider">AUDIO TRANSCRIPT REQUEST</div>}
              {msg.content}
            </div>
          </div>
        ))}
        {isProcessing && (
          <div className="flex justify-start w-full">
            <div className="bg-white border border-slate-200 p-4 rounded-2xl rounded-tl-none shadow-sm flex items-center gap-2">
                <div className="w-2 h-2 bg-indigo-500 rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></div>
                <div className="w-2 h-2 bg-indigo-500 rounded-full animate-bounce" style={{ animationDelay: '150ms' }}></div>
                <div className="w-2 h-2 bg-indigo-500 rounded-full animate-bounce" style={{ animationDelay: '300ms' }}></div>
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Input Area */}
      <div className="bg-white border-t border-slate-200 p-4">
        <div className="max-w-4xl mx-auto flex items-end gap-3">

          {/* File Upload Trigger */}
          <button 
             onClick={() => fileInputRef.current?.click()}
             className="p-3 text-slate-400 hover:text-indigo-600 transition-colors bg-slate-100 hover:bg-indigo-50 rounded-full"
             title="Upload Diagram/Image"
             disabled={isProcessing}
          >
             <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-6 h-6">
                <path strokeLinecap="round" strokeLinejoin="round" d="m2.25 15.75 5.159-5.159a2.25 2.25 0 0 1 3.182 0l5.159 5.159m-1.5-1.5 1.409-1.409a2.25 2.25 0 0 1 3.182 0l2.909 2.909m-18 3.75h16.5a1.5 1.5 0 0 0 1.5-1.5V6a1.5 1.5 0 0 0-1.5-1.5H3.75A1.5 1.5 0 0 0 2.25 6v12a1.5 1.5 0 0 0 1.5 1.5Zm10.5-11.25h.008v.008h-.008V8.25Zm.375 0a.375.375 0 1 1-.75 0 .375.375 0 0 1 .75 0Z" />
             </svg>
          </button>
          <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileUpload} />

          {/* Audio Recorder */}
          <AudioRecorder onRecordingComplete={handleAudioComplete} disabled={isProcessing} />

          {/* Text Input */}
          <div className="flex-1 bg-slate-100 rounded-2xl p-1 focus-within:ring-2 focus-within:ring-indigo-500 transition-shadow">
            <textarea
              value={inputText}
              onChange={(e) => setInputText(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter' && !e.shiftKey) {
                  e.preventDefault();
                  handleSendText();
                }
              }}
              placeholder={isProcessing ? "AI is thinking..." : "Describe your invention..."}
              disabled={isProcessing}
              className="w-full bg-transparent border-none focus:ring-0 p-3 text-sm max-h-32 resize-none disabled:opacity-50"
              rows={1}
              style={{ minHeight: '44px' }}
            />
          </div>

          {/* Send Button */}
          <button
            onClick={handleSendText}
            disabled={!inputText.trim() || isProcessing}
            className="p-3 bg-indigo-600 text-white rounded-full hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
          >
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5">
              <path strokeLinecap="round" strokeLinejoin="round" d="M6 12 3.269 3.126A59.768 59.768 0 0 1 21.485 12 59.77 59.77 0 0 1 3.27 20.876L5.999 12Zm0 0h7.5" />
            </svg>
          </button>
        </div>
        <p className="text-center text-[10px] text-slate-400 mt-2">
            AI can make mistakes. Review generated text in the Live Preview.
        </p>
      </div>
    </div>
  );
};

export default ChatInterface;

