import { GoogleGenAI, Type } from "@google/genai";
import { IDFData, Message, AIResponseSchema } from '../types';
import { SYSTEM_INSTRUCTION } from '../constants';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// We use 'gemini-2.5-flash-latest' for a balance of speed, multimodal, and reasoning.
const MODEL_NAME = 'gemini-2.5-flash-latest';

export interface AIInputData {
    text?: string;
    audioBase64?: string;
    media?: {
        mimeType: string;
        data: string; // base64 for binary, raw string for text
        isText?: boolean;
    };
}

export const generateAIResponse = async (
  currentData: IDFData,
  history: Message[],
  newItem: AIInputData
): Promise<AIResponseSchema> => {

  try {
    const parts: any[] = [];

    // Contextualize the model with the current state of the form
    const stateContext = `
      CURRENT IDF STATE (JSON):
      ${JSON.stringify(currentData, null, 2)}

      INSTRUCTION:
      Analyze the USER INPUT below. 
      1. Extract relevant technical or legal info to update the IDF STATE.
      2. Formulate the next follow-up question based on the empty fields in the priority order defined in the system instructions.
      3. If the user asks to "Submit", ensure all critical fields are filled, then set status to 'submitted' only if ready.
    `;

    parts.push({ text: stateContext });

    // Add History (last 5 messages for context, preventing token overflow)
    const recentHistory = history.slice(-5);
    recentHistory.forEach(msg => {
       if (msg.role !== 'system') {
           parts.push({ text: `${msg.role.toUpperCase()}: ${msg.content}` });
       }
    });

    // Add new user input
    parts.push({ text: "USER INPUT (New):" });

    if (newItem.text) {
      parts.push({ text: newItem.text });
    }

    // Handle Media (Images, PDFs, Text Files)
    if (newItem.media) {
        if (newItem.media.isText) {
             // For text files, we append the content directly as text to the prompt
             parts.push({ text: `\n[ATTACHED FILE CONTENT]\n${newItem.media.data}\n[END ATTACHED FILE]\n` });
        } else {
            // For binary files (Images, PDF)
            parts.push({
                inlineData: {
                  mimeType: newItem.media.mimeType,
                  data: newItem.media.data
                }
            });
        }
    }

    // Handle Audio
    if (newItem.audioBase64) {
       parts.push({
        inlineData: {
          mimeType: 'audio/mp3',
          data: newItem.audioBase64
        }
      });
    }

    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            updatedFields: {
              type: Type.OBJECT,
              properties: {
                inventorName: { type: Type.STRING },
                inventorEmail: { type: Type.STRING },
                title: { type: Type.STRING },
                problem: { type: Type.STRING },
                solution: { type: Type.STRING },
                technicalDetails: { type: Type.STRING },
                inventorsList: { type: Type.STRING },
                testingDates: { type: Type.STRING },
                publicDisclosures: { type: Type.STRING },
                upcomingDisclosures: { type: Type.STRING },
                diagramDescription: { type: Type.STRING },
              }
            },
            aiResponse: { type: Type.STRING },
          },
          required: ["aiResponse"]
        }
      },
      contents: {
        parts: parts
      }
    });

    if (response.text) {
      return JSON.parse(response.text) as AIResponseSchema;
    }

    throw new Error("No response from AI");

  } catch (error) {
    console.error("Gemini API Error:", error);
    return {
      updatedFields: {},
      aiResponse: "I'm having trouble processing that file or request right now. Please try again."
    };
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { Message, IDFData } from '../types';
import AudioRecorder from './AudioRecorder';
import { generateAIResponse, AIInputData } from '../services/geminiService';

interface ChatInterfaceProps {
  messages: Message[];
  setMessages: React.Dispatch<React.SetStateAction<Message[]>>;
  idfData: IDFData;
  setIDFData: React.Dispatch<React.SetStateAction<IDFData>>;
  onSave: () => void;
  onSubmit: () => void;
}

const ChatInterface: React.FC<ChatInterfaceProps> = ({ 
  messages, 
  setMessages, 
  idfData, 
  setIDFData,
  onSave,
  onSubmit
}) => {
  const [inputText, setInputText] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  // Helper to process AI response
  const processInput = async (
      text: string | undefined, 
      audioBlob: Blob | undefined, 
      file: File | undefined
  ) => {
    setIsProcessing(true);
    const timestamp = Date.now();

    // 1. Add User Message to UI
    let userContent = text || '';
    let msgType: 'text' | 'audio' | 'image' | 'file' = 'text';
    let displayFileName = undefined;

    if (audioBlob) {
        userContent = '🎤 [Audio Recorded]';
        msgType = 'audio';
    } else if (file) {
        const isImage = file.type.startsWith('image/');
        msgType = isImage ? 'image' : 'file';
        userContent = isImage ? `🖼️ [Image Uploaded]` : `📄 [File Uploaded]`;
        displayFileName = file.name;
    }

    const newMessage: Message = {
      id: `msg-${timestamp}`,
      role: 'user',
      content: userContent,
      type: msgType,
      fileName: displayFileName,
      timestamp
    };

    const newHistory = [...messages, newMessage];
    setMessages(newHistory);
    setInputText('');

    // 2. Prepare Payload for Gemini
    const aiInput: AIInputData = { text };

    if (audioBlob) {
        const reader = new FileReader();
        reader.readAsDataURL(audioBlob);
        await new Promise(resolve => reader.onloadend = resolve);
        // data:audio/mp3;base64,.....
        const base64Result = reader.result as string;
        aiInput.audioBase64 = base64Result.split(',')[1];
    }

    if (file) {
        // Determine how to read the file
        // Text-based files
        const isText = file.type === 'text/plain' || 
                       file.name.endsWith('.txt') || 
                       file.name.endsWith('.md') || 
                       file.name.endsWith('.csv') ||
                       file.name.endsWith('.json');

        if (isText) {
            const textContent = await file.text();
            aiInput.media = {
                mimeType: 'text/plain',
                data: textContent,
                isText: true
            };
        } else {
            // Binary files (PDF, Images)
            // Note: For unsupported binaries (like docx without conversion), this might fail at API level if not 'application/pdf' or image.
            // We pass them as base64 inlineData.
            const reader = new FileReader();
            reader.readAsDataURL(file);
            await new Promise(resolve => reader.onloadend = resolve);
            const base64Result = reader.result as string;

            aiInput.media = {
                mimeType: file.type,
                data: base64Result.split(',')[1],
                isText: false
            };
        }
    }

    // 3. Call AI
    const aiResult = await generateAIResponse(idfData, newHistory, aiInput);

    // 4. Update State
    if (aiResult.updatedFields) {
        const updatedData = { ...idfData, ...aiResult.updatedFields };
        setIDFData(updatedData);
    }

    // 5. Add AI Response to UI
    const aiMessage: Message = {
        id: `msg-${Date.now()}`,
        role: 'assistant',
        content: aiResult.aiResponse,
        timestamp: Date.now()
    };
    setMessages(prev => [...prev, aiMessage]);

    // Trigger auto-save in parent
    setTimeout(onSave, 100); 

    setIsProcessing(false);
  };

  const handleSendText = () => {
    if (!inputText.trim()) return;
    processInput(inputText, undefined, undefined);
  };

  const handleAudioComplete = (blob: Blob) => {
      processInput(undefined, blob, undefined);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files[0]) {
          processInput(undefined, undefined, e.target.files[0]);
      }
      // Reset input
      if(fileInputRef.current) fileInputRef.current.value = '';
  };

  return (
    <div className="flex flex-col h-full bg-slate-50 relative">
      {/* Session Guard Header */}
      <div className="bg-indigo-50 text-indigo-800 text-xs px-4 py-2 text-center border-b border-indigo-100 flex justify-between items-center">
        <span>Session Secure • Auto-saving</span>
        <button 
            onClick={onSubmit}
            className="bg-green-600 text-white px-3 py-1 rounded hover:bg-green-700 text-xs font-bold transition-colors shadow-sm"
        >
            SUBMIT DISCLOSURE
        </button>
      </div>

      {/* Messages Area */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {messages.map((msg) => (
          <div
            key={msg.id}
            className={`flex w-full ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
          >
            <div
              className={`max-w-[85%] p-4 rounded-2xl shadow-sm text-sm leading-relaxed ${
                msg.role === 'user'
                  ? 'bg-indigo-600 text-white rounded-tr-none'
                  : 'bg-white border border-slate-200 text-slate-800 rounded-tl-none'
              }`}
            >
              {msg.type === 'image' && <div className="text-xs opacity-75 mb-1 font-bold tracking-wider flex items-center gap-1">
                 <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                 IMAGE ATTACHMENT: {msg.fileName}
              </div>}
              {msg.type === 'file' && <div className="text-xs opacity-75 mb-1 font-bold tracking-wider flex items-center gap-1">
                 <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>
                 FILE ATTACHMENT: {msg.fileName}
              </div>}
              {msg.type === 'audio' && <div className="text-xs opacity-75 mb-1 font-bold tracking-wider">AUDIO TRANSCRIPT REQUEST</div>}
              {msg.content}
            </div>
          </div>
        ))}
        {isProcessing && (
          <div className="flex justify-start w-full">
            <div className="bg-white border border-slate-200 p-4 rounded-2xl rounded-tl-none shadow-sm flex items-center gap-2">
                <div className="w-2 h-2 bg-indigo-500 rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></div>
                <div className="w-2 h-2 bg-indigo-500 rounded-full animate-bounce" style={{ animationDelay: '150ms' }}></div>
                <div className="w-2 h-2 bg-indigo-500 rounded-full animate-bounce" style={{ animationDelay: '300ms' }}></div>
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Input Area */}
      <div className="bg-white border-t border-slate-200 p-4">
        <div className="max-w-4xl mx-auto flex items-end gap-3">

          {/* File Upload Trigger */}
          <button 
             onClick={() => fileInputRef.current?.click()}
             className="p-3 text-slate-400 hover:text-indigo-600 transition-colors bg-slate-100 hover:bg-indigo-50 rounded-full"
             title="Upload File (Image, PDF, TXT, MD)"
             disabled={isProcessing}
          >
             <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-6 h-6">
                <path strokeLinecap="round" strokeLinejoin="round" d="m18.375 12.739-7.693 7.693a4.5 4.5 0 0 1-6.364-6.364l10.94-10.94A3 3 0 1 1 19.5 7.372L8.552 18.32m.009-.01-.01.01m5.699-9.941-7.81 7.81a1.5 1.5 0 0 0 2.112 2.13" />
             </svg>
          </button>
          {/* Accept generic images, PDFs, and text files */}
          <input 
            type="file" 
            ref={fileInputRef} 
            className="hidden" 
            accept="image/*,application/pdf,.txt,.md,.csv,.json" 
            onChange={handleFileUpload} 
          />

          {/* Audio Recorder */}
          <AudioRecorder onRecordingComplete={handleAudioComplete} disabled={isProcessing} />

          {/* Text Input */}
          <div className="flex-1 bg-slate-100 rounded-2xl p-1 focus-within:ring-2 focus-within:ring-indigo-500 transition-shadow">
            <textarea
              value={inputText}
              onChange={(e) => setInputText(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter' && !e.shiftKey) {
                  e.preventDefault();
                  handleSendText();
                }
              }}
              placeholder={isProcessing ? "AI is analyzing..." : "Describe your invention..."}
              disabled={isProcessing}
              className="w-full bg-transparent border-none focus:ring-0 p-3 text-sm max-h-32 resize-none disabled:opacity-50"
              rows={1}
              style={{ minHeight: '44px' }}
            />
          </div>

          {/* Send Button */}
          <button
            onClick={handleSendText}
            disabled={!inputText.trim() || isProcessing}
            className="p-3 bg-indigo-600 text-white rounded-full hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
          >
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5">
              <path strokeLinecap="round" strokeLinejoin="round" d="M6 12 3.269 3.126A59.768 59.768 0 0 1 21.485 12 59.77 59.77 0 0 1 3.27 20.876L5.999 12Zm0 0h7.5" />
            </svg>
          </button>
        </div>
        <p className="text-center text-[10px] text-slate-400 mt-2">
            AI can make mistakes. Review generated text in the Live Preview.
        </p>
      </div>
    </div>
  );
};

