      INSTRUCTION:
      Analyze the USER INPUT below. 
      1. Extract relevant technical or legal info to update the IDF STATE.
      2. Formulate the next follow-up question based on the empty fields in the priority order defined in the system instructions.
      3. If the user asks to "Submit", ensure all critical fields are filled, then set status to 'submitted' only if ready.
    `;

    parts.push({ text: stateContext });

    // Add History (last 5 messages for context, preventing token overflow)
    const recentHistory = history.slice(-5);
    recentHistory.forEach(msg => {
       if (msg.role !== 'system') {
           parts.push({ text: `${msg.role.toUpperCase()}: ${msg.content}` });
       }
    });

    // Add new user input
    parts.push({ text: "USER INPUT (New):" });

    if (newItem.text) {
      parts.push({ text: newItem.text });
    }

    // Handle Media (Images, PDFs, Text Files)
    if (newItem.media) {
        if (newItem.media.isText) {
             // For text files, we append the content directly as text to the prompt
             parts.push({ text: `\n[ATTACHED FILE CONTENT]\n${newItem.media.data}\n[END ATTACHED FILE]\n` });
        } else {
            // For binary files (Images, PDF)
            parts.push({
                inlineData: {
                  mimeType: newItem.media.mimeType,
                  data: newItem.media.data
                }
            });
        }
    }

    // Handle Audio
    if (newItem.audioBase64) {
       parts.push({
        inlineData: {
          mimeType: 'audio/mp3',
          data: newItem.audioBase64
        }
      });
    }

    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            updatedFields: {
              type: Type.OBJECT,
              properties: {
                inventorName: { type: Type.STRING },
                inventorEmail: { type: Type.STRING },
                title: { type: Type.STRING },
                problem: { type: Type.STRING },
                solution: { type: Type.STRING },
                technicalDetails: { type: Type.STRING },
                inventorsList: { type: Type.STRING },
                testingDates: { type: Type.STRING },
                publicDisclosures: { type: Type.STRING },
                upcomingDisclosures: { type: Type.STRING },
                diagramDescription: { type: Type.STRING },
              }
            },
            aiResponse: { type: Type.STRING },
          },
          required: ["aiResponse"]
        }
      },
      contents: {
        parts: parts
      }
    });

    if (response.text) {
      return JSON.parse(response.text) as AIResponseSchema;
    }

    throw new Error("No response from AI");

  } catch (error: any) {
    console.error("Gemini API Error:", error);

    // Provide a user-friendly error message if possible
    let errorMessage = "I'm having trouble processing that request. Please try again.";

    if (error.message?.includes("404") || error.message?.includes("not found")) {
        errorMessage = "Service configuration error: The AI model is temporarily unavailable (404).";
    }

    return {
      updatedFields: {},
      aiResponse: errorMessage
    };
  }
};

export enum Phase {
  PROBLEM = 'PHASE_1_PROBLEM',
  SOLUTION = 'PHASE_2_SOLUTION',
  LEGAL = 'PHASE_3_LEGAL',
}

export interface MediaAsset {
  id: string;
  type: 'image' | 'file' | 'audio';
  name: string;
  mimeType: string;
  data: string; // Base64
  timestamp: number;
}

export interface IDFData {
  // Metadata
  currentPhase: Phase;
  mediaAssets: MediaAsset[];
  status: 'draft' | 'submitted';

  // Content
  inventorName: string;
  inventorEmail: string;
  title: string;
  problem: string;
  solution: string;
  technicalDetails: string;
  inventorsList: string;
  testingDates: string;
  publicDisclosures: string;
  upcomingDisclosures: string;
  diagramDescription?: string;
}

export interface Message {
  id: string;
  role: 'user' | 'assistant' | 'system';
  content: string;
  type?: 'text' | 'audio' | 'image' | 'file';
  fileName?: string;
  timestamp: number;
  phase: Phase; // Track which phase this message belongs to
}

export interface SessionState {
  sessionId: string;
  messages: Message[];
  data: IDFData;
  lastUpdated: number;
}

export enum AppMode {
  LANDING = 'LANDING',
  INVENTOR = 'INVENTOR',
  ATTORNEY = 'ATTORNEY',
}

export interface AIResponseSchema {
  updatedFields: Partial<IDFData>;
  aiResponse: string;
  nextPhase?: boolean; // Signal to move to next phase
}

import { SessionState, IDFData, Message, Phase } from '../types';
import { INITIAL_IDF_DATA } from '../constants';

const STORAGE_KEY_PREFIX = 'smart_idf_session_';

export const getSession = (sessionId: string): SessionState | null => {
  const stored = localStorage.getItem(`${STORAGE_KEY_PREFIX}${sessionId}`);
  if (!stored) return null;
  return JSON.parse(stored);
};

export const createSession = (sessionId: string): SessionState => {
  const newSession: SessionState = {
    sessionId,
    messages: [{
      id: 'init',
      role: 'assistant',
      content: "Welcome. I'm SmartDisclosure. Let's start with the basics. What is your full name and the working title of your invention?",
      timestamp: Date.now(),
      phase: Phase.PROBLEM, // Explicitly start in Phase 1
      type: 'text'
    }],
    data: { ...INITIAL_IDF_DATA },
    lastUpdated: Date.now()
  };
  saveSession(newSession);
  return newSession;
};

export const saveSession = (session: SessionState): void => {
  localStorage.setItem(`${STORAGE_KEY_PREFIX}${session.sessionId}`, JSON.stringify(session));
};

export const submitSession = (sessionId: string): void => {
    const session = getSession(sessionId);
    if(session) {
        session.data.status = 'submitted';
        saveSession(session);
    }
}

import { GoogleGenAI, Type } from "@google/genai";
import { IDFData, Message, AIResponseSchema, Phase } from '../types';
import { getSystemInstruction } from '../constants';

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
const MODEL_NAME = 'gemini-2.0-flash-exp';

export interface AIInputData {
    text?: string;
    audioBase64?: string;
    media?: {
        mimeType: string;
        data: string; // base64
        isText?: boolean;
    };
}

export const generateAIResponse = async (
  currentData: IDFData,
  history: Message[],
  newItem: AIInputData
): Promise<AIResponseSchema> => {

  try {
    const parts: any[] = [];
    const currentPhase = currentData.currentPhase;

    // 1. Get Phase-Specific System Instruction
    const systemInstruction = getSystemInstruction(currentPhase);

    // 2. Build Context
    const stateContext = `
      CURRENT IDF STATE (JSON):
      ${JSON.stringify(currentData, null, 2)}

      INSTRUCTION FOR PHASE: ${currentPhase}
      Review the conversation history.
      - If I asked for clarification on a vague answer previously, and the user is still vague, provide the 3-option list.
      - If the user uploaded a file in this turn, SUMMARIZE it and ASK FOR CONFIRMATION.
    `;

    parts.push({ text: stateContext });

    // 3. Add History (filtered to relevant context if needed, but last 10 is usually safe)
    const recentHistory = history.slice(-10);
    recentHistory.forEach(msg => {
       if (msg.role !== 'system') {
           // We might include phase info in history to help model understand context switches
           parts.push({ text: `[Phase: ${msg.phase}] ${msg.role.toUpperCase()}: ${msg.content}` });
       }
    });

    // 4. Add new user input
    parts.push({ text: "USER INPUT (New):" });

    if (newItem.text) {
      parts.push({ text: newItem.text });
    }

    // Handle Media
    if (newItem.media) {
        if (newItem.media.isText) {
             parts.push({ text: `\n[ATTACHED FILE CONTENT]\n${newItem.media.data}\n[END ATTACHED FILE]\n` });
        } else {
            parts.push({
                inlineData: {
                  mimeType: newItem.media.mimeType,
                  data: newItem.media.data
                }
            });
        }
    }

    if (newItem.audioBase64) {
       parts.push({
        inlineData: {
          mimeType: 'audio/mp3',
          data: newItem.audioBase64
        }
      });
    }

    // 5. Call API
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            updatedFields: {
              type: Type.OBJECT,
              properties: {
                // Phase 1
                inventorName: { type: Type.STRING },
                inventorEmail: { type: Type.STRING },
                title: { type: Type.STRING },
                problem: { type: Type.STRING },
                // Phase 2
                solution: { type: Type.STRING },
                technicalDetails: { type: Type.STRING },
                diagramDescription: { type: Type.STRING },
                // Phase 3
                inventorsList: { type: Type.STRING },
                testingDates: { type: Type.STRING },
                publicDisclosures: { type: Type.STRING },
                upcomingDisclosures: { type: Type.STRING },
              }
            },
            aiResponse: { type: Type.STRING },
            nextPhase: { type: Type.BOOLEAN, description: "Set to true ONLY if all goals for the current phase are met and confirmed." }
          },
          required: ["aiResponse"]
        }
      },
      contents: {
        parts: parts
      }
    });

    if (response.text) {
      return JSON.parse(response.text) as AIResponseSchema;
    }

    throw new Error("No response from AI");

  } catch (error: any) {
    console.error("Gemini API Error:", error);
    return {
      updatedFields: {},
      aiResponse: "I encountered an error processing your request. Please try again."
    };
  }
};

